import math, json, random, hashlib
from collections import Counter,defaultdict
from vs import corpus, ivtff

N=18; SEEDS=30
HASHES={'ZL3b-n.txt':'bf5b6d4ac1e3a51b1847a9c388318d609020441ccd56984c901c32b09beccafc', 'IT2a-n.txt':'7f27a8b0feed8f6de0a99900df6bf912dd1d295c38e5f830bac8b41c3f536fb5', 'RF1b-e.txt':'e7d3238e35743e06c63367a933909ec37b1e2de7ada3a1b449447eafa1918782'}
for name,digest in HASHES.items():
    with open('data/raw/'+name,'rb') as f: assert hashlib.sha256(f.read()).hexdigest()==digest, name

def cl(w):
    g=ivtff.segment(w); first=g[0]; prefix={'q':0,'o':1,'ch':2,'sh':3,'d':4}.get(first,5)
    size=0 if len(g)<=3 else 1 if len(g)<=6 else 2
    return prefix*3+size

def rows(pages):
    out=[]
    for p in pages:
        for line in p.lines:
            if line.unit!='P' or len(line.words)<2: continue
            n=len(line.words)
            for i in range(1,n):
                a,b=line.words[i-1:i+1]
                if ivtff.uncertain(a) or ivtff.uncertain(b): continue
                if not all(c.isalpha() and c.isascii() and c.islower() for c in a+b): continue
                pos=min(3,4*i//n); out.append((p.id,p.section or '?',pos,cl(a),cl(b)))
    return out

def fit(rr):
    base=defaultdict(Counter); trans=defaultdict(Counter); pred=defaultdict(list); counts=Counter()
    for f,s,p,a,b in rr: base[s,p][b]+=1; trans[a][b]+=1; counts[b]+=1; pred[s,p].append(a)
    total=sum(counts.values()); globalp=[(counts[i]+.5)/(total+.5*N) for i in range(N)]
    def dist(c,alpha):
        n=sum(c.values()); return [(c[i]+alpha*globalp[i])/(n+alpha) for i in range(N)]
    return {'base':{k:dist(c,20) for k,c in base.items()},'trans':{k:dist(c,20) for k,c in trans.items()},'pred':pred,'global':globalp}

def evaluate(rr,model,w,override=None,byfolio=False):
    lossb=losst=0; group=defaultdict(list)
    for i,(f,s,p,a,b) in enumerate(rr):
        if override is not None: a=override[i]
        d=model['base'].get((s,p),model['global']); t=model['trans'].get(a,model['global'])
        lb=-math.log(d[b]); lt=-math.log((1-w)*d[b]+w*t[b]);lossb+=lb;losst+=lt;group[f].append(lb-lt)
    return lossb/len(rr),losst/len(rr),group

def trial(trans):
    tr,ev=corpus.split_pages('practice',trans)
    dev=[p for p in tr if int(hashlib.sha256(p.id.encode()).hexdigest()[:8],16)%5==0]; train=[p for p in tr if p not in dev]
    rtrain,rdev,rtest=rows(train),rows(dev),rows(ev); model=fit(rtrain)
    weights=[i/20 for i in range(21)]
    w=min(weights,key=lambda x:evaluate(rdev,model,x)[1]); b,t,group=evaluate(rtest,model,w)
    rng=random.Random(42107); placebo=[]
    allpred=[v for x in model['pred'].values() for v in x]
    for _ in range(SEEDS):
        pred=[rng.choice(model['pred'].get((s,p),allpred)) for f,s,p,a,y in rtest]
        pb,pt,_=evaluate(rtest,model,w,pred); placebo.append(pb-pt)
    sums={k:(sum(v),len(v)) for k,v in group.items()}; ids=list(sums); boots=[]
    for _ in range(1000):
        picked=rng.choices(ids,k=len(ids)); boots.append(sum(sums[k][0] for k in picked)/sum(sums[k][1] for k in picked))
    boots.sort()
    return {'folio_counts':[len(train),len(dev),len(ev)],'pair_counts':[len(rtrain),len(rdev),len(rtest)],'mixture_weight':w,'baseline_nll':round(b,6),'transition_nll':round(t,6),'gain':round(b-t,6),'placebo_gain_range':[round(min(placebo),6),round(max(placebo),6)],'folio_bootstrap_interval':[round(boots[24],6),round(boots[974],6)],'positive_folios':sum(sum(v)>0 for v in group.values()),'test_folios_with_pairs':len(group)}

if __name__=='__main__': print(json.dumps({t:trial(t) for t in ('zl','it','rf')},indent=2))
